package com.kartyavya.report.security; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; @Service public class JwtService { @Value("${security.jwt.secret}")String secret;@Value("${security.jwt.issuer}")String issuer;@Value("${security.jwt.audience}")String audience;public Claims parse(String t){return Jwts.parser().verifyWith(Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8))).requireIssuer(issuer).requireAudience(audience).build().parseSignedClaims(t).getPayload();}}
